S.tcBoard=()=>`
 ${IDEA("نفس الأعمدة السبعة اللي في الكود، بس الكارت بيقول الكرة في ملعب مين: عندنا ولا عند العميل («متابعة العميل مطلوبة»)، ومتعلّق ليه، ومين شغال عليه حالاً. شريط «شغالين دلوقتي» بيغني عن السؤال في الجروب، وتوزيع الحمل تحت بيوضح مين عليه ضغط قبل ما تسند له مهمة جديدة.")}
 ${HEAD("لوحة المهام","اسحب البطاقات بين الأعمدة أو رتّبها جوه العمود، واضغط على أي بطاقة لتفاصيلها.",`<span class="tc-kbd">اختصارات: <kbd>N</kbd> بطاقة جديدة · <kbd>/</kbd> بحث</span>`+B("primary","plus","بطاقة جديدة",'data-go="tcForm"'))}
 ${tcTabs("tcBoard")}
 <div class="fbar"><div class="fb grow"><label>بحث</label><div class="inp">${X("search")}<input placeholder="ابحث بالرقم أو العنوان أو العميل"></div></div><div class="fb"><label>العميل</label>${SEL(["كل العملاء","مكتب الريادة","مؤسسة سواعد","مكتب الأمانة","مكتب نجد"])}</div><div class="fb"><label>النوع</label>${SEL(["كل الأنواع",...Object.keys(TY).filter(k=>k!=="GEN").map(k=>k+" — "+TY[k][1])])}</div><div class="fb"><label>المسؤول</label>${SEL(["كل المسؤولين",...PPL])}</div></div>
 <div class="tc-fl"><div class="cx-chips">${[["مهامي",9],["متأخرة",4,"r"],["متابعة عميل",3,"a"],["طارئ",2,"r"]].map((c,i)=>`<button class="${i===1?"on":""}">${c[2]?`<i class="d ${c[2]}"></i>`:""}${c[0]}<b class="num">${c[1]}</b></button>`).join("")}</div><a href="#" class="tc-clear">مسح الفلاتر</a>
  <div class="tc-now"><b>شغالين دلوقتي <span class="num">4</span></b>${[["أحمد سمير","UPD-0812","1:12"],["منى عادل","DATA-0061","0:34"],["كريم فتحي","OPS-0033","0:08"],["سارة نبيل","GEN-0001","0:21"]].map(p=>`<span class="tc-np">${av(p[0])}<span><b>${p[0].split(" ")[0]}</b><small class="num">${p[1]} · ${p[2]}</small></span></span>`).join("")}</div></div>
 <div class="tc-board">${COLS.map(c=>{const it=TK.filter(r=>r[4]===c[0]);return `<div class="tc-col ${c[0]}"><div class="tc-ch"><i class="d ${STC[c[0]]}"></i><b>${c[1]}</b><span class="num">${it.length}</span></div><div class="tc-cb">${it.map(card).join("")}${c[0]==="client"?`<div class="tc-hint">${X("info")}بتتعلّم «متابعة مطلوبة» بعد تاريخ المتابعة أو 3 أيام عمل.</div>`:""}</div>${c[0]==="closed"?`<div class="tc-cfoot muted">المغلق يختفي بعد 30 يوم</div>`:`<button class="tc-cfoot">${X("plus")}إضافة بطاقة</button>`}</div>`}).join("")}</div>
 <div class="grid-2">
  ${SEC("zap","إضافة سريعة من تحت العمود",`<div class="tc-qc"><textarea rows="2" placeholder="عنوان البطاقة… (Enter للإضافة)">تقرير الإيرادات حسب المندوب</textarea><div class="fgrid">${FLD("النوع",SEL(["UPD — تحديث","BUG — خطأ","DATA — مشكلة بيانات","OPS — سيرفرات ونشر","MTG — متابعة واجتماع","SUP — استفسار ودعم"]))}${FLD("الأولوية",SEL(["متوسط","طارئ","مهم","منخفض"]))}${FLD("العميل",SEL(["مكتب الريادة","مؤسسة سواعد"]))}${FLD("المشروع / مركز التكلفة",SEL(["الريادة — اشتراك ERP","الريادة — تطوير خاص"]))}${FLD("المسؤول",SEL(["أنا (أحمد سمير)",...PPL.slice(1)]))}${FLD("الاستحقاق",INP("","19/11/2026",1),0,"افتراضي: بعد 3 أيام عمل")}</div><div class="cx-right"><a href="#" data-go="tcForm" class="tc-clear">النموذج الكامل</a>${B("primary sm","plus","إضافة بطاقة")}</div></div>`)}
  ${SEC("scale","توزيع الحمل على الفريق",`<small class="tc-sub" style="display:block;padding:0 20px 10px">مهام مفتوحة لكل واحد — الأحمر = عنده متأخر.</small><div class="tc-load">${[["أحمد سمير",9,2],["منى عادل",7,0],["كريم فتحي",6,1],["يوسف حسن",4,0],["سارة نبيل",5,1],["عمر خالد",2,0]].map(p=>`<div>${av(p[0])}<b>${p[0]}</b><span class="tc-bar"><i style="width:${p[1]*10}%"></i>${p[2]?`<i class="r" style="width:${p[2]*10}%"></i>`:""}</span><em class="num">${p[1]}${p[2]?` · <span class="tc-late">${p[2]} متأخر</span>`:""}</em></div>`).join("")}</div>`)}
 </div>
 <div class="tc-moves">${[["pause","لو نقلتها لـ «معلّق»","هيطلب سبب التعليق، وبيظهر على الكارت."],["user-check","لو نقلتها لـ «بانتظار قبول العميل»","هيطلب تاريخ المتابعة مع العميل (افتراضي بعد 3 أيام عمل)."],["lock","لو نقلتها لـ «مغلق»","هيقفل أي مؤقت شغال عليها ويسجّل تاريخ الإغلاق."]].map(m=>`<div>${X(m[0])}<span><b>${m[1]}</b><small>${m[2]}</small></span></div>`).join("")}</div>`;

/* ================= صفحة المهمة ================= */
S.tcTask=()=>{const steps=["جديد","قيد التنفيذ","اختبار داخلي","جاهز للنشر","بانتظار قبول العميل","مغلق"];return `
 ${IDEA("صفحة المهمة مبنية على سؤالين: المهمة فين في المسار؟ وأنا أعمل إيه دلوقتي؟ — المسار فوق بالخطوة الحالية، والعمود الجانبي ثابت فيه المؤقت ونقل الحالة. الوقت والتكلفة قصاد التقدير بشريط، فلو المهمة عدّت تقديرها يبان قبل ما تتقفل.")}
 <div class="page-head compact"><div><a class="back" href="#" data-go="tcBoard" style="margin:0 0 8px">${X("arrow-right")}<span>لوحة المهام</span></a><h1>تقرير العمولات بيحسب الكوبون مرتين ${TAG("r","متأخرة")}</h1><p><span class="num">BUG-0147</span> · ${ty("BUG")} خطأ · <span class="tc-pr r">طارئ</span> · مكتب الريادة · آخر تحديث من ساعتين</p></div><div class="actions">${B("ghost","pencil","تعديل",'data-go="tcForm"')+B("ghost","columns-3","اللوحة",'data-go="tcBoard"')}</div></div>
 <div class="card fx-track">${steps.map((s,i)=>`<div class="s ${i<2?"done":i===2?"now":""}"><span class="n">${i<2?X("check"):`<b class="num">${i+1}</b>`}</span><div><b>${s}</b><small>${i===0?"12 نوفمبر":i===1?"13 نوفمبر":i===2?"من امبارح":""}</small></div></div>`).join(`<i class="l"></i>`)}</div>
 <div class="grid-2 wide-l"><div>
  ${SEC("align-right","الوصف",`<div class="tc-desc"><p>لما العقد يكون عليه كوبون خصم، تقرير العمولات بيخصم قيمة الكوبون مرة من الإجمالي ومرة تانية من صافي العمولة، فالمندوب بياخد أقل من المستحق.</p><p><b>المتوقع:</b> الكوبون يتخصم مرة واحدة من أساس العمولة حسب قاعدة «حماية العمولة» في إعدادات الكوبونات.</p><p><b>للتجربة:</b> عقد CN-2026-0115 · كوبون RAMADAN26.</p></div>`,`<span class="tc-sub">المطلوب تنفيذه والنتيجة المتوقعة</span>`)}
  ${SEC("list-checks","قائمة التحقق",`<div class="tc-ck"><div class="tc-ckp"><span class="num">3 من 5 مكتملة · 60%</span><span class="tc-bar"><i style="width:60%"></i></span></div>${[["إعادة إنتاج المشكلة على نسخة الاختبار",1,"أحمد"],["تعديل حساب أساس العمولة في CommissionService",1,"أحمد"],["اختبار عقد بكوبون نسبة",1,"منى"],["اختبار عقد بكوبون مبلغ ثابت",0],["مراجعة التقرير القديم للشهر اللي فات",0]].map(c=>`<label class="${c[1]?"on":""}"><input type="checkbox" ${c[1]?"checked":""}><span>${c[0]}</span>${c[2]?`<small>${c[2]}</small>`:""}</label>`).join("")}<div class="tc-ckadd"><div class="inp grow"><input placeholder="أضف خطوة أو حالة اختبار..."></div>${B("ghost sm","plus","إضافة")}</div></div>`)}
  ${SEC("messages-square","النقاش والتحديثات",`<div class="tc-cm">${[["منى عادل","من ساعة","اختبرت كوبون النسبة على CN-2026-0115 — العمولة طلعت صح 1,150 ر.س. فاضل المبلغ الثابت.",""],["أحمد سمير","امبارح 16:40","الإصلاح اترفع على نسخة الاختبار. نقلتها لاختبار داخلي.","commission-fix.png"],["سارة نبيل","13 نوفمبر","العميل بعت صورة التقرير اللي فيه الفرق.","report-oct.pdf"]].map(c=>`<div>${av(c[0])}<div><b>${c[0]} <small>${c[1]}</small></b><p>${c[2]}</p>${c[3]?`<a href="#" class="tc-file">${X("paperclip")}${c[3]}</a>`:""}</div></div>`).join("")}<div class="tc-comp"><textarea rows="2" placeholder="اكتب تحديثًا، سؤالًا، أو نتيجة اختبار..."></textarea><div>${B("ghost sm","paperclip","إرفاق ملف")}${B("primary sm","send","إرسال التعليق")}</div></div></div>`,`<span class="tc-sub num">3 تعليقات</span>`)}
  <div class="card flush fx-t"><div class="card-h pad"><div><h3>سجل الوقت</h3></div></div><div class="tw fit"><table><thead><tr><th>الموظف</th><th>البداية</th><th>المدة · التكلفة</th><th>النوع والحالة</th></tr></thead><tbody>${[["أحمد سمير","16 نوفمبر 10:20","2:10","مؤقت",TAG("g","معتمد"),"156"],["أحمد سمير","16 نوفمبر 09:02","0:56","مؤقت",TAG("g","معتمد"),"67"],["منى عادل","15 نوفمبر 14:00","1:30","يدوي — «اختبرت من جهاز العميل»",TAG("a","بانتظار الموافقة"),"—"],["أحمد سمير","13 نوفمبر 11:15","3:05","مؤقت · بدون لقطات شاشة",TAG("a","بانتظار الموافقة"),"—"]].map(r=>`<tr><td>${r[0]}</td><td class="num">${r[1]}</td><td class="num"><b>${r[2]}</b><small style="display:block;color:var(--muted)">${r[5]==="—"?"—":r[5]+" ر.س"}</small></td><td><small style="display:block">${r[3]}</small>${r[4]}</td></tr>`).join("")}</tbody></table></div></div>
  <details class="card tc-det"><summary>${X("git-commit-horizontal")}<b>سجل تغيّر الحالة (<span class="num">3</span>)</b></summary><div class="tc-log">${[["امبارح 16:40","قيد التنفيذ ← اختبار داخلي","أحمد سمير"],["13 نوفمبر 11:15","جديد ← قيد التنفيذ","تلقائي مع تشغيل المؤقت"],["12 نوفمبر 10:02","أُنشئت — المصدر: لايف شات","سارة نبيل"]].map(l=>`<div><span class="num">${l[0]}</span><b>${l[1]}</b><em>${l[2]}</em></div>`).join("")}</div></details>
 </div><div class="fx-side">
  <div class="card sec tc-tbox"><div class="sec-h">${X("timer")}<b>تسجيل الوقت</b></div><div class="tc-tb">${B("primary","play","ابدأ هنا بدل المهمة الحالية")}<small>شغال دلوقتي على <span class="num">UPD-0812</span> — هيتقفل ويبدأ هنا. ستفتح نافذة المراقبة بعد نجاح التشغيل.</small>
   <div class="tc-est"><div><small>المسجل المعتمد</small><b class="num">3:06</b></div><div><small>التقديري</small><b class="num">4:00</b></div><div><small>التكلفة</small><b class="num">223 ر.س</b></div></div><span class="tc-bar"><i style="width:78%"></i></span><small class="tc-sub">78% من التقدير · <span class="num">4:35</span> لو اتعتمد المعلّق</small></div></div>
  ${SEC("route","الحالة والمتابعة",`<div class="fgrid one">${FLD("نقل إلى",SEL(["اختبار داخلي","جاهز للنشر","بانتظار قبول العميل","معلّق","مغلق","قيد التنفيذ","جديد"]))}${FLD("ملاحظة الحركة",INP("سبب التعليق أو ملاحظة الحركة"))}${FLD("موعد متابعة العميل",INP("","",1,"date"),0,"بيظهر لما تختار «بانتظار قبول العميل».")}</div><div class="cx-right">${B("primary sm","save","حفظ الحالة")}</div>`)}
  ${SEC("info","تفاصيل المهمة",KV([["الأولوية",`<span class="tc-pr r">طارئ</span>`],["العميل","مكتب الريادة"],["المشروع","الريادة — اشتراك ERP"],["المسؤول",`${av("أحمد سمير","sm")} أحمد سمير`],["المراجِع",`${av("منى عادل","sm")} منى عادل`],["الاستحقاق",`<span class="num tc-late">16 نوفمبر</span>`],["المنتج","Click ERP System"],["المصدر","لايف شات"],["أنشأها","سارة نبيل"]]))}
  <details class="card tc-det"><summary>${X("plus-circle")}<b>إضافة وقت يدوي</b></summary><small class="tc-sub" style="display:block;padding:0 20px">لوقت لم يُسجل بالمؤقت، ويحتاج اعتماد مدير.</small><div class="fgrid" style="padding:12px 20px">${FLD("التاريخ",INP("","16/11/2026",1))}${FLD("ساعات / دقائق",`<div class="tc-hm">${INP("","1",1)}<span>:</span>${INP("","30",1)}</div>`)}${FLD("السبب",INP("5 حروف على الأقل"),1,"",1)}</div><div class="cx-right" style="padding:0 20px 16px">${B("ghost sm","send","إرسال للموافقة")}</div></details>
  <div class="card tc-help">${X("monitor-up")}<div><b>تحتاج مساعدة مباشرة؟</b><small>اطلب من المسؤول جلسة يشوف فيها شاشتك (RustDesk بعد موافقتك).</small></div>${B("ghost sm","","اطلب جلسة",'data-go="tcSessions"')}</div>
 </div></div>`};

