S.tcForm=()=>`
 ${IDEA("الفورم بيقول قبل الحفظ رقم المهمة هيبقى إيه، وموعدها الافتراضي، ومين عليه حمل — عشان النوع ثابت بعد الإنشاء (جزء من الرقم) والإسناد يبقى عن معرفة.")}
 ${HEAD("مهمة جديدة","الحقول المعلّمة بـ * إلزامية. النوع ثابت بعد الإنشاء لأنه جزء من رقم المهمة.",B("ghost","","إلغاء",'data-go="tcBoard"')+B("primary","save","حفظ"),["tcBoard","لوحة المهام"])}
 <div class="grid-2 wide-l"><div>
  ${FS(1,"إيه المطلوب؟",`<div class="fgrid">${FLD("النوع",`<div class="tc-types">${Object.keys(TY).filter(k=>k!=="GEN").map((k,i)=>`<label class="${i===1?"on":""}">${ty(k)}<span>${TY[k][1]}</span></label>`).join("")}</div>`,1,"",1)}${FLD("العنوان",INP("","إضافة فلتر المندوب في تقرير الإيرادات"),1,"",1)}${FLD("الوصف",TXT("المطلوب تنفيذه والنتيجة المتوقعة",4),0,"",1)}</div>`)}
  ${FS(2,"لمين؟",`<div class="fgrid">${FLD("العميل",SEL(["مؤسسة سواعد","مكتب الريادة","مكتب الأمانة","مكتب نجد"]),1)}${FLD("المشروع / مركز التكلفة",`<select><optgroup label="مؤسسة سواعد"><option>سواعد — اشتراك ERP</option><option>سواعد — تطوير خاص</option></optgroup></select>`,1)}${FLD("المنتج / الوحدة",SEL(["Click ERP System","Click Chat","نظام تأجير بالساعة","مواقع خارجية","تطبيقات"]))}${FLD("المصدر",SEL(["عميل","لايف شات","Slack","داخلي","اختبار"]))}</div>`)}
  ${FS(3,"مين وإمتى؟",`<div class="fgrid">${FLD("الأولوية",`<div class="cx-seg2 in"><button>طارئ</button><button>مهم</button><button class="on">متوسط</button><button>منخفض</button></div>`,1)}${FLD("تاريخ الاستحقاق",INP("","19/11/2026",1),1,"افتراضي: بعد 3 أيام عمل")}${FLD("المسؤول",SEL(["يوسف حسن — 4 مهام مفتوحة",...PPL.map(p=>p)]),1)}${FLD("المراجِع / المختبِر",SEL(["منى عادل","—",...PPL]))}${FLD("الساعات التقديرية",INP("","6",1,"number"),0,"بخطوات ربع ساعة")}</div>`)}
 </div><div>
  <div class="card sec fx-sum"><div class="sec-h">${X("ticket")}<b>ملخص</b></div><div class="fx-sum-amt"><small>رقم المهمة هيبقى</small><b class="num">UPD-0817</b><span>النوع جزء من الرقم ومش هيتغير بعد الحفظ</span></div>${KV([["العمود","جديد"],["الاستحقاق","الأربعاء 19 نوفمبر"],["المسؤول","يوسف حسن"],["تكلفة تقديرية","≈ 430 ر.س"]])}</div>
  ${SEC("scale","حمل الفريق الحالي",`<div class="tc-load">${[["يوسف حسن",4,0],["عمر خالد",2,0],["سارة نبيل",5,1],["منى عادل",7,0],["أحمد سمير",9,2]].map(p=>`<div>${av(p[0])}<b>${p[0]}</b><span class="tc-bar"><i style="width:${p[1]*10}%"></i>${p[2]?`<i class="r" style="width:${p[2]*10}%"></i>`:""}</span><em class="num">${p[1]}</em></div>`).join("")}</div>`)}
 </div></div>`;

