const MINE=[["BUG-0147","تقرير العمولات بيحسب الكوبون مرتين","أحمد سمير","منى عادل","اختبار","من ساعة","الإصلاح على نسخة الاختبار. جرّبي كوبون نسبة وكوبون مبلغ ثابت على CN-2026-0115.",["كوبون نسبة","كوبون مبلغ ثابت","تقرير الشهر اللي فات"]],
 ["DATA-0061","تكرار عملاء بعد الاستيراد من Excel","منى عادل","أحمد سمير","مراجعة كود","من 3 ساعات","سكربت الدمج جاهز — راجع شرط الجوال قبل ما أشغّله على نسخة العميل.",["شرط الدمج بالجوال","نسخة احتياطية قبل التشغيل"]],
 ["SUP-0288","شرح إعداد الفروع لموظف جديد","عمر خالد","أحمد سمير","استلام (إجازة)","أمس","هبقى إجازة يومين — العميل مستني مكالمة الأحد 11 الصبح.",["رقم العميل في المهمة"]]];
